js:function(context, args) {
  var actor = args && args.actor;
  if (typeof actor !== 'string' || !actor.length) return {defer: 'missing current arguments', parameters: 'actor (string)'};
  var hist = (context && context.history) || [];
  var submitted = false, callId = null, terminal = false, receipt = null, journal = null;
  for (var i = 0; i < hist.length; i++) {
    var t = hist[i];
    journal = t;
    var argv = t && t.decoded_argv;
    var cmd = t && t.arguments && t.arguments.command;
    if ((argv && argv[0] === 'experiment' && argv[1] === 'submit') || (typeof cmd === 'string' && cmd.indexOf('experiment submit') === 0)) {
      submitted = true;
      if (t.data && t.data.native_operation_id) callId = t.data.native_operation_id;
      if (!callId) { var m = String(cmd || '').match(/call_[A-Za-z0-9_]+/); if (m) callId = m[0]; }
    }
    if (t && t.data && t.data.native_operation_id && !callId) callId = t.data.native_operation_id;
    if (t && t.data && t.data.complete === true) { callId = t.data.native_operation_id || callId; terminal = true; receipt = t.data; }
  }
  if (!terminal && !submitted) {
    var a = execute({name: 'bash', arguments: {command: command('experiment', ['submit', actor])}, read: false, step: 'submit', occurrence: 0});
    journal = a;
    if (a && a.data && a.data.native_operation_id) callId = a.data.native_operation_id;
    if (!callId && a && a.text) { var ma = String(a.text).match(/call_[A-Za-z0-9_]+/); if (ma) callId = ma[0]; }
  }
  if (!terminal && callId) {
    var polls = 0;
    while (polls < 60) {
      polls++;
      var p = execute({name: 'bash', arguments: {command: command('experiment', ['status', callId])}, read: true});
      journal = p || journal;
      if (p && p.data && p.data.native_operation_id) callId = p.data.native_operation_id;
      if (p && p.data && p.data.complete === true) { terminal = true; receipt = p.data; break; }
    }
  }
  if (terminal && receipt) return {report: {actor: actor, native_operation_id: callId, complete: true, count: receipt.count, status: receipt.status, receipt: receipt}};
  return {defer: 'experiment operation not yet complete; no success is claimed', evidence: {last: journal}};
}
